var e={en:`During month-end reporting, checkout p95 grows from 200 ms to 1.8 s due to heavy joins and long-lived transactions.`,ua:`Під час місячної звітності p95 checkout зростає з 200 мс до 1,8 с через важкі JOIN та довгі транзакції.`};var t={en:[`Highlight reporting contention and transaction-lock dependencies.`,`Add a read projection or asynchronous reporting job.`,`Document freshness, backfill and reconciliation without requiring new services.`],ua:[`Познач конкуренцію звітів і транзакційні блокування.`,`Додай проєкцію читання або фонову звітність.`,`Опиши актуальність, наповнення та звірення без зайвих сервісів.`]};var i=[{en:`Reports no longer lock critical checkout writes.`,ua:`Звіти більше не блокують критичні записи checkout.`},{en:`Domain modules still own their transactional data.`,ua:`Доменні модулі зберігають власність транзакційних даних.`}];var c={scenario:e,tasks:t,checks:i};export{i as checks,c as default,e as scenario,t as tasks};